-- =====================================================================
-- ТОЛЬКО ДЛЯ ЛОКАЛЬНЫХ ИНТЕГРАЦИОННЫХ ТЕСТОВ. На сервере не выполнять.
--
-- Заглушки существующих таблиц проекта. Имена столбцов совпадают
-- со значениями по умолчанию в config/complaints.php
-- (complaints_project_schema). Если в проекте столбцы называются иначе,
-- поправьте конфиг, а здесь — только для своих тестов.
-- Столбцы срока обжалования trd_buy добавляет миграция 002.
-- =====================================================================

CREATE TABLE trd_buy (
    id               bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    number_anno      varchar(50)  NOT NULL,
    name_ru          varchar(500) NOT NULL,
    name_kz          varchar(500) NOT NULL,
    method_id        bigint       NOT NULL,
    organizer_org_id bigint       NOT NULL,
    published_at     timestamptz  NOT NULL
);

CREATE TABLE trd_buy_lot (
    id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    trd_buy_id bigint       NOT NULL REFERENCES trd_buy (id),
    lot_number varchar(50)  NOT NULL,
    name_ru    varchar(500) NOT NULL,
    name_kz    varchar(500) NOT NULL
);

CREATE TABLE trd_app (
    id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    trd_buy_id      bigint NOT NULL REFERENCES trd_buy (id),
    supplier_org_id bigint NOT NULL,
    status_id       bigint NOT NULL
);

CREATE TABLE trd_app_lot (
    id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    trd_app_id     bigint NOT NULL REFERENCES trd_app (id),
    trd_buy_lot_id bigint NOT NULL REFERENCES trd_buy_lot (id),
    status_id      bigint NOT NULL
);
